proc sort data= JAR_Data.Amadeus_2009disk;
BY Mark;
run;

proc transpose data=JAR_Data.Amadeus_2009disk_aa out=JAR_Data.Amadeus_2009disk_8 prefix=turnover;
by mark;
var turnover_year_0-turnover_year_9;
run;

data JAR_Data.Amadeus_2009disk_combined;
merge JAR_Data.Amadeus_2009disk_numeric(in=a) JAR_Data.Amadeus_2009disk_static (in=b);
by Mark;
if a and b;
run;

data JAR_Data.Oriana_historical_financials;
set JAR_Data.Orbis_historical_financials;
keep BvD_ID_number Consolidation_code Closing_date Audit_status Accounting_practice 
Fixed_assets Total_assets Operating_revenue__Turnover_ Sales P_L_for_period___Net_income_ P_L_after_tax Long_term_debt Loans Cash___cash_equivalent Shareholders_funds Capital Current_assets Current_liabilities Creditors Debtors Working_capital Depreciation___Amortization Costs_of_goods_sold Cash_flow Number_of_employees;
if substr(left(Closing_date),1,4) in ('1999','2000','2001','2002','2003','2004','2005','2006','2007','2008','2009','2010','2011','2012','2013','2014','2015','2016','2017') 
and substr(BvD_ID_number,1,2)in ('AU','BH','BD','CN','FJ','HK','IN','ID','IR','IQ','IL','JP','JO','KZ','KW','KG','LB','MY','MH','NP','NZ','OM','PK','PS','PG','PH','QA','RU','SA','SG','KR','LK','SY','TW','TH','TR','AE','VU','VN','YE')then output;

data JAR_Data.Orbis_historical_financials_1;
set JAR_Data.Orbis_historical_financials_1;
Year=substr(left(Closing_date),1,4);
Country=substr(BvD_ID_number,1,2);
run;

data JAR_Data.Oriana_industrycode;
set JAR_Data.Orbis_industrycode;
keep BvD_ID_number NACE_Rev__2__Core_code__4_digits US_SIC__Primary_code_s_ ;
if substr(BvD_ID_number,1,2)in ('AU','BH','BD','CN','FJ','HK','IN','ID','IR','IQ','IL','JP','JO','KZ','KW','KG','LB','MY','MH','NP','NZ','OM','PK','PS','PG','PH','QA','RU','SA','SG','KR','LK','SY','TW','TH','TR','AE','VU','VN','YE')then output;
run;

proc sort JAR_Data.Oriana_industrycode out=patstat.Oriana_industrycode nodupkey;
   by BvD_ID_number;
run;

data JAR_Data.Oriana_legalinfo;
set JAR_Data.Orbis_legalinfo;
keep BvD_ID_number Status Standardised_legal_form Date_of_incorporation Listed_Delisted_Unlisted Delisted_date IPO_date;
if substr(BvD_ID_number,1,2)in ('AU','BH','BD','CN','FJ','HK','IN','ID','IR','IQ','IL','JP','JO','KZ','KW','KG','LB','MY','MH','NP','NZ','OM','PK','PS','PG','PH','QA','RU','SA','SG','KR','LK','SY','TW','TH','TR','AE','VU','VN','YE')then output;
run;

proc sql noprint;
create table JAR_Data.Oriana_data_merged as
select a.*, b.*, c.* from
JAR_Data.Oriana_historical_financials a LEFT JOIN JAR_Data.Oriana_industrycode b
on a.BvD_ID_number=b.BvD_ID_number
LEFT JOIN JAR_Data.Oriana_legalinfo c
on a.BvD_ID_number=c.BvD_ID_number;
quit;

data JAR_Data.Amadeus_2009disk_static; set JAR_Data.Amadeus_2009disk;
Keep Mark Company_Name bvdep_id_number city country_initials cons_code nace_rev_2__primary_code isin_number sedol_number
     ticker_symbol legal_status legal_form date_of_incorporation publicly_quoted ipo_date delisted_date main_exchange reporting_basis indep__ind_ naics_2007__core_code us_sic__core_code
     auditor_name;

foreach var of varlist sales fix_assets total_assets {
gen lag_`var'=`var'[_n-1] if bvd_id==bvd_id[_n-1] & year==year[_n-1]+1
gen chg_`var'=`var'-lag_`var'
gen `var'_gr=(`var'-lag_`var')/lag_`var'
}

foreach var of varlist cash1 longterm_debt1 loans1{
replace `var'=0 if `var'==.
}

foreach var of varlist inv roa lev ln_at sales_gr cash_s total_assets_gr fix_assets_gr hhi {
winsor2 `var', replace cuts(1 99) by(year)
}

PROC EXPORT DATA=SDF.CUSTOMER
              FILE="&tmpdir.customer.dta"
              DBMS=STATA REPLACE;

